package com.schedora.controller;
import com.schedora.model.*; import com.schedora.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import java.time.*; import java.time.format.DateTimeFormatter; import java.time.format.DateTimeParseException;
@RestController @RequestMapping("/api")
public class ApiController {
 private final UserRepository users; private final ServiceRepository services; private final BookingRepository bookings; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); private final Map<String,Long> tokens=new ConcurrentHashMap<>();
 public ApiController(UserRepository u,ServiceRepository s,BookingRepository b){users=u;services=s;bookings=b;}
 private ResponseEntity<?> error(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}
 private UserAccount current(String auth){if(auth==null||!auth.startsWith("Bearer "))return null;Long id=tokens.get(auth.substring(7));return id==null?null:users.findById(id).orElse(null);}
 private Map<String,Object> profile(UserAccount u,String token){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.getId());m.put("name",u.getName());m.put("email",u.getEmail());m.put("role",u.getRole());m.put("businessName",u.getBusinessName());if(token!=null)m.put("token",token);return m;}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","application","Schedora API");}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@RequestBody Map<String,String> r){String name=clean(r.get("name")),email=clean(r.get("email")).toLowerCase(),password=r.get("password"),role=clean(r.get("role")).toLowerCase(),business=clean(r.get("businessName"));if(name.isBlank()||email.isBlank()||password==null||password.length()<8)return error(HttpStatus.BAD_REQUEST,"Name, email and a password of at least 8 characters are required.");if(!role.equals("user")&&!role.equals("owner"))return error(HttpStatus.BAD_REQUEST,"Choose user or owner account.");if(role.equals("owner")&&business.isBlank())return error(HttpStatus.BAD_REQUEST,"Business name is required for owner accounts.");if(users.findByEmailIgnoreCase(email).isPresent())return error(HttpStatus.CONFLICT,"An account with this email already exists. Please log in.");UserAccount u=users.save(new UserAccount(name,email,encoder.encode(password),role,role.equals("owner")?business:null));String token=UUID.randomUUID().toString();tokens.put(token,u.getId());return ResponseEntity.status(HttpStatus.CREATED).body(profile(u,token));}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String> r){String email=clean(r.get("email")).toLowerCase(),password=r.get("password"),role=clean(r.get("role")).toLowerCase();Optional<UserAccount> found=users.findByEmailIgnoreCase(email);if(found.isEmpty()||password==null||!encoder.matches(password,found.get().getPasswordHash())||!found.get().getRole().equals(role))return error(HttpStatus.UNAUTHORIZED,"Invalid email, password, or account type.");String token=UUID.randomUUID().toString();tokens.put(token,found.get().getId());return ResponseEntity.ok(profile(found.get(),token));}
 @PostMapping("/auth/logout") public ResponseEntity<?> logout(@RequestHeader(value="Authorization",required=false) String auth){if(auth!=null&&auth.startsWith("Bearer "))tokens.remove(auth.substring(7));return ResponseEntity.ok(Map.of("message","Signed out."));}
 @GetMapping("/services") public List<Map<String,Object>> allServices(){return services.findAll().stream().map(this::serviceMap).toList();}
 @PostMapping("/services") public ResponseEntity<?> addService(@RequestHeader(value="Authorization",required=false) String auth,@RequestBody Map<String,Object> r){UserAccount u=current(auth);if(u==null)return error(HttpStatus.UNAUTHORIZED,"Please log in.");if(!u.getRole().equals("owner"))return error(HttpStatus.FORBIDDEN,"Only business owners can add services.");try{String name=clean(str(r,"name")),cat=clean(str(r,"category")),loc=clean(str(r,"location")),duration=clean(str(r,"duration"));int price=Integer.parseInt(String.valueOf(r.get("price")));if(name.isBlank()||cat.isBlank()||loc.isBlank()||duration.isBlank()||price<0)return error(HttpStatus.BAD_REQUEST,"Fill in all service fields with a valid price.");ServiceListing s=services.save(new ServiceListing(name,cat,u.getBusinessName(),loc,price,duration,u));return ResponseEntity.status(HttpStatus.CREATED).body(serviceMap(s));}catch(Exception e){return error(HttpStatus.BAD_REQUEST,"Invalid service details.");}}
 @DeleteMapping("/services/{id}") public ResponseEntity<?> deleteService(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable Long id){UserAccount u=current(auth);if(u==null)return error(HttpStatus.UNAUTHORIZED,"Please log in.");ServiceListing s=services.findById(id).orElse(null);if(s==null)return error(HttpStatus.NOT_FOUND,"Service not found.");if(!s.getOwner().getId().equals(u.getId()))return error(HttpStatus.FORBIDDEN,"You can remove only your own services.");if(bookings.findByServiceOwnerIdOrderByCreatedAtDesc(u.getId()).stream().anyMatch(b->b.getService().getId().equals(id)&&!b.getStatus().equals("Cancelled")))return error(HttpStatus.CONFLICT,"This service has bookings. Cancel those bookings before removing it.");services.delete(s);return ResponseEntity.noContent().build();}
 @GetMapping("/services/{id}/availability") public ResponseEntity<?> availability(@PathVariable Long id,@RequestParam String date){
  if(!validDate(date))return error(HttpStatus.BAD_REQUEST,"Use a valid date in YYYY-MM-DD format.");
  if(LocalDate.parse(date).isBefore(LocalDate.now()))return error(HttpStatus.BAD_REQUEST,"Past dates are not available.");
  if(services.findById(id).isEmpty())return error(HttpStatus.NOT_FOUND,"Service not found.");
  List<String> booked=bookings.findByServiceIdAndAppointmentDateAndStatusNot(id,date,"Cancelled").stream().map(Booking::getAppointmentTime).toList();
  List<String> slots=List.of("09:00 AM","10:00 AM","11:00 AM","12:00 PM","01:00 PM","02:00 PM","03:00 PM","04:00 PM","05:00 PM","06:00 PM");
  if(LocalDate.parse(date).equals(LocalDate.now())){LocalTime now=LocalTime.now();slots=slots.stream().filter(t->parseSlot(t).isAfter(now)).toList();}
  return ResponseEntity.ok(Map.of("date",date,"slots",slots,"bookedSlots",booked));
 }
 @PostMapping("/bookings") public ResponseEntity<?> createBooking(@RequestHeader(value="Authorization",required=false) String auth,@RequestBody Map<String,String> r){UserAccount u=current(auth);if(u==null)return error(HttpStatus.UNAUTHORIZED,"Please log in.");if(!u.getRole().equals("user"))return error(HttpStatus.FORBIDDEN,"Only user accounts can book appointments.");try{Long serviceId=Long.valueOf(r.get("serviceId"));ServiceListing s=services.findById(serviceId).orElse(null);if(s==null)return error(HttpStatus.NOT_FOUND,"Service not found.");String date=clean(r.get("date")),time=clean(r.get("time")),notes=clean(r.get("notes"));if(date.isBlank()||time.isBlank())return error(HttpStatus.BAD_REQUEST,"Date and time are required.");if(!validDate(date))return error(HttpStatus.BAD_REQUEST,"Use a valid date in YYYY-MM-DD format.");if(LocalDate.parse(date).isBefore(LocalDate.now()))return error(HttpStatus.BAD_REQUEST,"Past dates cannot be booked.");if(!List.of("09:00 AM","10:00 AM","11:00 AM","12:00 PM","01:00 PM","02:00 PM","03:00 PM","04:00 PM","05:00 PM","06:00 PM").contains(time))return error(HttpStatus.BAD_REQUEST,"Choose a valid available time slot.");if(LocalDate.parse(date).equals(LocalDate.now())&&!parseSlot(time).isAfter(LocalTime.now()))return error(HttpStatus.BAD_REQUEST,"This time slot has already passed.");if(bookings.existsByServiceIdAndAppointmentDateAndAppointmentTimeAndStatusNot(serviceId,date,time,"Cancelled"))return error(HttpStatus.CONFLICT,"That slot is already booked. Please choose another time.");Booking b=bookings.save(new Booking(s,u,date,time,notes));return ResponseEntity.status(HttpStatus.CREATED).body(bookingMap(b));}catch(Exception e){return error(HttpStatus.BAD_REQUEST,"Invalid booking details.");}}
 @GetMapping("/bookings") public ResponseEntity<?> getBookings(@RequestHeader(value="Authorization",required=false) String auth){UserAccount u=current(auth);if(u==null)return error(HttpStatus.UNAUTHORIZED,"Please log in.");List<Booking> rows=u.getRole().equals("owner")?bookings.findByServiceOwnerIdOrderByCreatedAtDesc(u.getId()):bookings.findByCustomerIdOrderByCreatedAtDesc(u.getId());return ResponseEntity.ok(rows.stream().map(this::bookingMap).toList());}
 @PutMapping("/bookings/{id}/status") public ResponseEntity<?> status(@RequestHeader(value="Authorization",required=false) String auth,@PathVariable Long id,@RequestBody Map<String,String> r){UserAccount u=current(auth);if(u==null)return error(HttpStatus.UNAUTHORIZED,"Please log in.");if(!u.getRole().equals("owner"))return error(HttpStatus.FORBIDDEN,"Only business owners can update bookings.");Booking b=bookings.findById(id).orElse(null);if(b==null)return error(HttpStatus.NOT_FOUND,"Booking not found.");if(!b.getService().getOwner().getId().equals(u.getId()))return error(HttpStatus.FORBIDDEN,"This booking does not belong to your business.");String st=clean(r.get("status"));if(!List.of("Pending","Confirmed","Completed","Cancelled").contains(st))return error(HttpStatus.BAD_REQUEST,"Invalid status.");b.setStatus(st);return ResponseEntity.ok(bookingMap(bookings.save(b)));}
 private Map<String,Object> serviceMap(ServiceListing s){Map<String,Object> m=new LinkedHashMap<>();m.put("id",s.getId());m.put("name",s.getName());m.put("category",s.getCategory());m.put("business",s.getBusiness());m.put("location",s.getLocation());m.put("price",s.getPrice());m.put("duration",s.getDuration());m.put("ownerId",s.getOwner().getId());return m;}
 private Map<String,Object> bookingMap(Booking b){Map<String,Object> m=new LinkedHashMap<>();m.put("id",b.getId());m.put("serviceId",b.getService().getId());m.put("service",b.getService().getName());m.put("business",b.getService().getBusiness());m.put("date",b.getAppointmentDate());m.put("time",b.getAppointmentTime());m.put("status",b.getStatus());m.put("notes",b.getNotes());m.put("customer",b.getCustomer().getName());m.put("customerEmail",b.getCustomer().getEmail());m.put("customerId",b.getCustomer().getId());return m;}
 private boolean validDate(String value){try{LocalDate.parse(value,DateTimeFormatter.ISO_LOCAL_DATE);return true;}catch(Exception e){return false;}}
 private LocalTime parseSlot(String value){return LocalTime.parse(value,DateTimeFormatter.ofPattern("hh:mm a",Locale.ENGLISH));}
 private String clean(String v){return v==null?"":v.trim();} private String str(Map<String,Object> m,String k){Object v=m.get(k);return v==null?"":String.valueOf(v);}
}
